INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q33745', 'Peloponnesian War', 'The Peloponnesian War was fought in the Eastern Mediterranean between the Athenian-led Delian League and the Spartan-led Peloponnesian League from 431 to 404 BC for hegemony over Ancient Greece. Initially inconclusive, the intervention of the Persian Empire in support of Sparta in 413 BC allowed the Spartan coalition to decisively defeat Athens, beginning a period of Spartan hegemony over Greece.', -431, NULL, NULL, -404, 4, 25, 'year', '431 BCE – 25 April 404 BCE', 83, 'https://en.wikipedia.org/wiki/Peloponnesian_War'),
  ('Q655777', 'Battle of the Allia', 'The Battle of the Allia was fought c. 387 BC between the Senones – a Gallic tribe led by Brennus, who had invaded Northern Italy – and the Roman Republic. The battle was fought at the confluence of the Tiber river and Allia brook, 11 Roman miles (16 km, 10 mi) north of Rome.', -387, 7, 18, NULL, NULL, NULL, 'day', '18 July 387 BCE', 66, 'https://en.wikipedia.org/wiki/Battle_of_the_Allia'),
  ('Q744611', 'Battle of Heraclea', 'The Battle of Heraclea took place in 280 BC between the Romans under the command of consul Publius Valerius Laevinus, and the combined forces of Greeks from Epirus, Tarentum, Thurii, Metapontum, and Heraclea under the command of Pyrrhus, king of Epirus. Although the battle was a victory for the Greeks, they incurred severe losses.', -280, NULL, NULL, NULL, NULL, NULL, 'year', '280 BCE', 65, 'https://en.wikipedia.org/wiki/Battle_of_Heraclea'),
  ('Q756413', 'Battle of Asculum', 'The Battle of Asculum was a battle that took place near Asculum (modern Ascoli Satriano) in 279 BC, and was thought to have lasted either one or two days, between the Roman Republic under the command of the consuls Publius Decius Mus (who by some accounts died before the battle) and Publius Sulpicius Saverrio, and the forces of King Pyrrhus of Epirus. The battle took place during the Pyrrhic War, after the Battle of Heraclea of 280 BC, which was the first battle of the war.', -279, NULL, NULL, NULL, NULL, NULL, 'year', '279 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Asculum'),
  ('Q1160070', 'Battle of Beneventum', 'The Battle of Beneventum (275 BC) was the last battle of the Pyrrhic War. It was fought near Beneventum, in southern Italy, between the forces of Pyrrhus, king of Epirus in Greece, and the Romans, led by consul Manius Curius Dentatus.', -275, NULL, NULL, NULL, NULL, NULL, 'year', '275 BCE', 65, 'https://en.wikipedia.org/wiki/Battle_of_Beneventum_(275_BC)'),
  ('Q917376', 'Battle of Agrigentum', 'The Battle of Agrigentum (Sicily, 262 BC) was the first pitched battle of the First Punic War and the first large-scale military confrontation between Carthage and the Roman Republic. The battle was fought after a long siege which started in 262 BC and resulted both in a Roman victory and the beginning of Roman control of Sicily.', -261, NULL, NULL, NULL, NULL, NULL, 'year', '261 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Agrigentum'),
  ('Q277345', 'Battle of Mylae', 'The Battle of Mylae took place in 260 BC during the First Punic War and was the first real naval battle between Carthage and the Roman Republic. This battle was key in the Roman victory of Mylae (present-day Milazzo) as well as Sicily itself.', -260, NULL, NULL, NULL, NULL, NULL, 'year', '260 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Mylae'),
  ('Q1134649', 'Battle of the Aegates Islands', 'The Battle of the Aegates was a naval battle fought on 10 March 241 BC between the fleets of Carthage and Rome during the First Punic War. It took place among the Aegates Islands, off the western coast of the island of Sicily.', -241, NULL, NULL, NULL, NULL, NULL, 'year', '241 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_the_Aegates'),
  ('Q271873', 'Battle of the Trebia', 'The Battle of the Trebia (or Trebbia) was the first major battle of the Second Punic War, fought between the Carthaginian forces of Hannibal and a Roman army under Sempronius Longus on 22 or 23 December 218 BC. Each army had a strength of about 40,000 men; the Carthaginians were stronger in cavalry, the Romans in infantry. The battle took place on the flood plain of the west bank of the lower Trebia River, not far from the settlement of Placentia (modern Piacenza), and resulted in a heavy defeat for the Romans.', -218, 12, NULL, NULL, NULL, NULL, 'month', 'December 218 BCE', 71, 'https://en.wikipedia.org/wiki/Battle_of_the_Trebia'),
  ('Q378957', 'Battle of Ticinus', 'The Battle of Ticinus was fought between the Carthaginian forces of Hannibal and a Roman army under Publius Cornelius Scipio in late November 218 BC as part of the Second Punic War. It took place in the flat country on the right bank of the river Ticinus, to the west of modern Pavia in northern Italy.', -218, 11, NULL, NULL, NULL, NULL, 'month', 'November 218 BCE', 67, 'https://en.wikipedia.org/wiki/Battle_of_Ticinus'),
  ('Q207250', 'Battle of Lake Trasimene', 'The Battle of Lake Trasimene was fought when a Carthaginian force under Hannibal ambushed a Roman army commanded by Gaius Flaminius on 21 June 217 BC, during the Second Punic War. The battle took place on the north shore of Lake Trasimene, to the south of Cortona, and resulted in a heavy defeat for the Romans.', -217, 6, 21, NULL, NULL, NULL, 'day', '21 June 217 BCE', 72, 'https://en.wikipedia.org/wiki/Battle_of_Lake_Trasimene'),
  ('Q179591', 'Battle of Cannae', 'The Battle of Cannae (; Latin: [ˈkanːae̯]) was a key engagement of the Second Punic War between the Roman Republic and Carthage, fought on 2 August 216 BC near the ancient village of Cannae in Apulia, southeast Italy. The Carthaginians and their allies, led by Hannibal, surrounded and practically annihilated a larger Roman and Italian army under the consuls Lucius Aemilius Paullus and Gaius Terentius Varro.', -216, 8, 2, NULL, NULL, NULL, 'day', '2 August 216 BCE', 80, 'https://en.wikipedia.org/wiki/Battle_of_Cannae'),
  ('Q848056', 'Battle of the Metaurus', 'The Battle of the Metaurus was a pivotal battle in the Second Punic War between Rome and Carthage, fought in 207 BC near the Metauro River in Italy. The Carthaginians were led by Hasdrubal Barca, brother of Hannibal, who was to have brought siege equipment and reinforcements for Hannibal.', -207, NULL, NULL, NULL, NULL, NULL, 'year', '207 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_the_Metaurus'),
  ('Q618066', 'First Servile War', 'The First Servile War of 135–132 BC (also known as the First Sicilian Slave War) was a slave rebellion against the Roman Republic, which took place in Sicily. The revolt started in 135 when Eunus, a slave from Syria who claimed to be a prophet, captured the city of Enna in the middle of the island with 400 fellow slaves.', -135, NULL, NULL, -132, NULL, NULL, 'year', '135 BCE – 132 BCE', 65, 'https://en.wikipedia.org/wiki/First_Servile_War'),
  ('Q677316', 'Social War of 91-87 BCE', 'The Social War (from Latin bellum sociale, "war of the allies"), also known as the Italian War or the Marsic War, was fought between the Roman Republic and several of its autonomous allies (socii), largely from 91 to 88 BC in Italy, with some holdouts persisting until 87 BC. The war started in late 91 BC with the rebellion of Asculum. Other Italian towns also rebelled and the Roman response was initially confused.', -91, NULL, NULL, -88, NULL, NULL, 'year', '91 BCE – 88 BCE', 71, 'https://en.wikipedia.org/wiki/Social_War_(91%E2%80%9387_BC)'),
  ('Q339321', 'Battle of the Milvian Bridge', 'The Battle of the Milvian Bridge took place between the Roman Emperors Constantine I and Maxentius on 28 October AD 312. It takes its name from the Milvian Bridge, an important route over the Tiber.', 312, 10, 28, NULL, NULL, NULL, 'day', '28 October 312', 73, 'https://en.wikipedia.org/wiki/Battle_of_the_Milvian_Bridge'),
  ('Q1136575', 'Vandalic War', 'The Vandalic War (533–534) was a conflict fought in North Africa between the forces of the Byzantine Empire (also known as the Eastern Roman Empire) and the Germanic Vandal Kingdom. It was the first war of Emperor Justinian I''s Renovatio imperii Romanorum, wherein the Byzantines attempted to reassert Roman sovereignty over territory formerly controlled by the Western Roman Empire.', 533, 6, NULL, 534, 3, NULL, 'month', 'June 533 – March 534', 68, 'https://en.wikipedia.org/wiki/Vandalic_War'),
  ('Q769358', 'Battle of Taginae', 'The Battle of Taginae or Battle of Busta Gallorum took place in July 552 AD, where Byzantines led by Narses defeated the Ostrogoths (Goths) under King Totila in the late stages of the Gothic War (535–554). The Byzantine victory paved the way for the Byzantine reconquest of the Italian Peninsula and the dissolution of the Gothic Kingdom.', 552, 7, NULL, NULL, NULL, NULL, 'month', 'July 552', 63, 'https://en.wikipedia.org/wiki/Battle_of_Taginae'),
  ('Q1137764', 'Battle of Mons Lactarius', 'The Battle of Mons Lactarius took place in October 552 during the Gothic War (535–554) between Byzantine forces and the Ostrogoths (Goths) at Mount Lactarius near Mount Vesuvius in Italy. After the defeat and death of the Gothic King Totila at the Battle of Taginae, Teia was chosen as the new Gothic king, who attempted to gather allies and the remaining Gothic forces.', 552, 10, NULL, NULL, NULL, NULL, 'month', 'October 552', 62, 'https://en.wikipedia.org/wiki/Battle_of_Mons_Lactarius'),
  ('Q283364', 'Battle of Legnano', 'The Battle of Legnano was fought on 29 May 1176 between the army of Frederick Barbarossa, Holy Roman Emperor, and the forces of the Lombard League near Legnano, between Milan and Como, in the Kingdom of Italy. It was the climactic field engagement of Frederick''s fifth Italian campaign and one of the most consequential battles of the long conflict between the emperor, the northern Italian communes and Pope Alexander III. The encounter itself arose unexpectedly from manoeuvres by two armies that were aware of one another but did not possess precise information about the other''s position.', 1176, 5, 29, NULL, NULL, NULL, 'day', '29 May 1176', 66, 'https://en.wikipedia.org/wiki/Battle_of_Legnano'),
  ('Q283062', 'Battle of Benevento', 'The Battle of Benevento was a major medieval battle fought on 26 February 1266, near Benevento in present-day Southern Italy, between the forces of Charles I of Anjou and those of King Manfred of Sicily. Manfred''s defeat and death resulted in Charles'' conquest of the Kingdom of Sicily, effectively ending the rule of the Hohenstaufen dynasty in the Italian Peninsula and marking the rise of the royal Capetian House of Anjou.', 1266, 2, 26, NULL, NULL, NULL, 'day', '26 February 1266', 64, 'https://en.wikipedia.org/wiki/Battle_of_Benevento'),
  ('Q1474884', 'High Renaissance', 'In art history, the High Renaissance was a short period of the most exceptional artistic production in the Italian states, particularly Rome, capital of the Papal States, and in Florence, during the Italian Renaissance. Most art historians state that the High Renaissance started between 1490 and 1500, and ended in 1520 with the death of Raphael, although some say it ended around 1525, in 1527 with the Sack of Rome by the mutinous army of Charles V, Holy Roman Emperor, or around 1530.', 1494, NULL, NULL, 1527, NULL, NULL, 'year', '1494–1527', 65, 'https://en.wikipedia.org/wiki/High_Renaissance'),
  ('Q330', 'Battle of Marignano', 'The Battle of Marignano, (or bataille de Marignan in French) which took place on 13–14 September 1515, near the town now called Melegnano, 16 km southeast of Milan, was the last major engagement of the War of the League of Cambrai. It pitted the French army, led by Francis I, newly crowned King of France, against the Old Swiss Confederacy.', 1515, 9, 13, 1515, 9, 14, 'day', '13 September 1515 – 14 September 1515', 69, 'https://en.wikipedia.org/wiki/Battle_of_Marignano'),
  ('Q698281', 'Italian War of 1521–1526', 'The Italian War of 1521–1526, sometimes known as the Four Years'' War (French: Sixième guerre d''Italie, lit. ''sixth war of Italy''), was a part of the Italian Wars. The war pitted Francis I of France and the Republic of Venice against the Holy Roman Emperor Charles V, Henry VIII of England, and the Papal States.', 1521, NULL, NULL, 1526, NULL, NULL, 'year', '1521–1526', 65, 'https://en.wikipedia.org/wiki/Italian_War_of_1521%E2%80%931526'),
  ('Q63468', 'Battle of Pavia', 'The Battle of Pavia, fought on the morning of 24 February 1525, was the decisive engagement of the Italian War of 1521–1526 between the Kingdom of France and the Habsburg Empire of Charles V, Holy Roman Emperor as well as ruler of Spain, Austria, the Low Countries, and the Two Sicilies. The French army was led by King Francis I of France, who laid siege to the city of Pavia (then part of the Duchy of Milan within the Holy Roman Empire) in October 1524 with 26,200 troops.', 1525, 2, 24, NULL, NULL, NULL, 'day', '24 February 1525', 70, 'https://en.wikipedia.org/wiki/Battle_of_Pavia'),
  ('Q1429256', 'War of the League of Cognac', 'The War of the League of Cognac (1526–1530) was fought between the Habsburg dominions of Emperor Charles V—chiefly the Holy Roman Empire and Spain—and the League of Cognac, an alliance comprising the Kingdom of France, Pope Clement VII, the Republic of Venice, the Duchy of Milan and the Republic of Florence, later joined by the Kingdom of England. The war is best known for the Sack of Rome by the Emperor''s unpaid troops in 1527, an event that some historians regard as the end of the Italian Renaissance.', 1526, NULL, NULL, 1530, NULL, NULL, 'year', '1526–1530', 64, 'https://en.wikipedia.org/wiki/War_of_the_League_of_Cognac'),
  ('Q776609', 'Battle of the Bridge of Arcole', 'The Battle of Arcole or Battle of Arcola (15–17 November 1796) (French: Bataille du pont d''Arcole, German: Schlacht bei Arcole) was fought between French and Austrian forces 25 kilometres (16 mi) southeast of Verona during the War of the First Coalition, a part of the French Revolutionary Wars. The battle saw a bold maneuver by Napoleon Bonaparte''s French Army of Italy to outflank the Austrian army led by József Alvinczi and cut off its line of retreat.', 1796, 11, 15, 1796, 11, 17, 'day', '15 November 1796 – 17 November 1796', 62, 'https://en.wikipedia.org/wiki/Battle_of_Arcole'),
  ('Q900945', 'Battle of Lodi', 'The Battle of Lodi was fought on Tuesday 10 May 1796 between French forces under General Napoleon Bonaparte and an Austrian rear guard commanded by Karl Philipp Sebottendorf at Lodi, Lombardy (then part of the Habsburg monarchy, now in Italy), being one of the key engagements of the Italian Campaign. The conflict took place as French forces pursued the retreating Austrian army across the Adda River.', 1796, 5, 10, NULL, NULL, NULL, 'day', '10 May 1796', 65, 'https://en.wikipedia.org/wiki/Battle_of_Lodi'),
  ('Q273011', 'Battle of Marengo', 'The Battle of Marengo was fought on 14 June 1800 between French forces under the First Consul Napoleon Bonaparte and Austrian forces near the city of Alessandria, in Piedmont, Italy. Near the end of the day, the French overcame General Michael von Melas''s surprise attack, drove the Austrians out of Italy and consolidated Bonaparte''s political position in Paris as First Consul of France in the wake of his coup d''état the previous November.', 1800, 6, 14, NULL, NULL, NULL, 'day', '14 June 1800', 73, 'https://en.wikipedia.org/wiki/Battle_of_Marengo'),
  ('Q48202', 'Battle of Custoza', 'The First Battle of Custoza was fought on July 24 and 25, 1848, during the First Italian War of Independence between the armies of the Austrian Empire, commanded by Field Marshal Radetzky, and the Kingdom of Sardinia, led by King Charles Albert of Piedmont-Sardinia.', 1848, 7, 25, NULL, NULL, NULL, 'day', '25 July 1848', 64, 'https://en.wikipedia.org/wiki/Battle_of_Custoza_(1848)'),
  ('Q623164', 'Five Days of Milan', 'The Five Days of Milan (Italian: Cinque giornate di Milano [ˈtʃiŋkwe dʒorˈnaːte di miˈlaːno]) was an insurrection and a major event in the Revolutionary Year of 1848 that started the First Italian War of Independence. On 18 March, a rebellion arose in the city of Milan which in five days of street fighting drove Marshal Radetzky and his Austrian soldiers from the city.', 1848, 3, 18, 1848, 3, 22, 'day', '18 March 1848 – 22 March 1848', 69, 'https://en.wikipedia.org/wiki/Five_Days_of_Milan'),
  ('Q837787', 'Battle of Novara', 'The Battle of Novara (or Battle of Bicocca; Bicocca being a borough of Novara) was one of the battles fought between the Austrian Empire and the Kingdom of Sardinia during the First Italian War of Independence, within the era of Italian unification. Lasting the whole day of 22 March 1849 and ending at dawn on 23 March, it resulted in a severe defeat and retreat of the Piedmontese (Sardinian) army.', 1849, 3, 23, NULL, NULL, NULL, 'day', '23 March 1849', 64, 'https://en.wikipedia.org/wiki/Battle_of_Novara_(1849)'),
  ('Q324916', 'Battle of Solferino', 'The Battle of Solferino (referred to in Italy as the Battle of Solferino and San Martino) on 24 June 1859 was the climactic battle of the Second Italian War of Independence and resulted in the victory of the allied French army under Napoleon III and the Piedmont-Sardinian army under Victor Emmanuel II (together known as the Franco-Sardinian alliance) against the Austrian army under Emperor Franz Joseph I. It was the last major battle in world history in which all the armies were under the personal command of their monarchs. There were approximately 300,000 soldiers on both sides in the most…', 1859, 6, 24, NULL, NULL, NULL, 'day', '24 June 1859', 71, 'https://en.wikipedia.org/wiki/Battle_of_Solferino'),
  ('Q681430', 'Battle of Magenta', 'The Battle of Magenta (Italian pronunciation: [maˈdʒenta]) was fought on 4 June 1859 near the town of Magenta in the Kingdom of Lombardy–Venetia, a crown land of the Austrian Empire, during the Second Italian War of Independence. It resulted in a French-Sardinian victory under Napoleon III against the Austrians under Marshal Ferenc Gyulay.', 1859, 6, 4, NULL, NULL, NULL, 'day', '4 June 1859', 64, 'https://en.wikipedia.org/wiki/Battle_of_Magenta'),
  ('Q158054', 'Battle of Lissa', 'The Battle of Lissa (also known as the Battle of Vis; Croatian: Bitka kod Visa) was fought on 20 July 1866 between the Italian and Austrian navies near the island of Lissa in the Adriatic Sea during the Third Italian War of Independence. An Italian fleet under Admiral Carlo Pellion di Persano engaged an Austrian fleet led by Vice-Admiral Wilhelm von Tegetthoff in an attempt to break Austria''s naval dominance in the Adriatic.', 1866, 7, 20, NULL, NULL, NULL, 'day', '20 July 1866', 67, 'https://en.wikipedia.org/wiki/Battle_of_Lissa_(1866)'),
  ('Q2604547', 'Capture of Rome', 'The capture of Rome (Italian: Presa di Roma) occurred on 20 September 1870, as forces of the Kingdom of Italy took control of the city and of the Papal States. After a plebiscite held on 2 October 1870, Rome was officially made capital of Italy on 3 February 1871, completing the unification of Italy (Risorgimento).', 1870, 9, 20, NULL, NULL, NULL, 'day', '20 September 1870', 64, 'https://en.wikipedia.org/wiki/Capture_of_Rome'),
  ('Q1348910', '1908 Messina earthquake', 'A devastating earthquake occurred on 28 December 1908 in Sicily and Calabria, southern Italy, with a moment magnitude of 7.1 and a maximum Mercalli intensity of XI (Extreme). The epicentre was in the Strait of Messina which separates Sicily from the Italian mainland.', 1908, 12, 28, NULL, NULL, NULL, 'day', '28 December 1908', 68, 'https://en.wikipedia.org/wiki/1908_Messina_earthquake'),
  ('Q681517', 'Battles of the Isonzo', 'The Battles of the Isonzo (also known as the Isonzo Front by historians, or the Soča Front; Slovene: soška fronta) were a series of eleven or twelve battles between the Austro-Hungarian and Italian armies in World War I mostly on the territory of present-day Slovenia, and the remainder in Italy along the Isonzo (Slovene: Soča) River on the eastern sector of the Italian Front between June 1915 and November 1917.', 1915, 5, 23, 1917, 10, 27, 'day', '23 May 1915 – 27 October 1917', 64, 'https://en.wikipedia.org/wiki/Battles_of_the_Isonzo'),
  ('Q242644', 'Battle of Caporetto', 'The Battle of Caporetto (also known as the Twelfth Battle of the Isonzo, the Battle of Kobarid or the Battle of Karfreit) took place on the Isonzo front of World War I. The battle was fought between the Kingdom of Italy and the Central Powers and took place from 24 October to 19 November 1917, near the town of Kobarid (now in north-western Slovenia, then part of the Austrian Littoral), and near the river Isonzo. The battle was named after the Italian name of the town (also known as Karfreit in German).', 1917, 10, 24, 1917, 11, 19, 'day', '24 October 1917 – 19 November 1917', 73, 'https://en.wikipedia.org/wiki/Battle_of_Caporetto'),
  ('Q662947', 'Battle of the Piave River', 'The Second Battle of the Piave River (or Battle of the Solstice), fought between 15 and 23 June 1918, was a decisive victory for the Italian Army against the Austro-Hungarian Empire during World War I, as Italy was part of the Allied Forces, while Austria-Hungary was part of the Central Powers. Though the battle proved to be a decisive blow to the Austro-Hungarian Empire and by extension the Central Powers, its full significance was not initially appreciated in Italy.', 1918, 6, 23, 1918, 6, 25, 'day', '23 June 1918 – 25 June 1918', 64, 'https://en.wikipedia.org/wiki/Second_Battle_of_the_Piave_River'),
  ('Q662961', 'Battle of Vittorio Veneto', 'The Battle of Vittorio Veneto was fought from 24 October to 4 November 1918 near Vittorio Veneto on the Italian Front during World War I. After having defeated Austro-Hungarian troops during the Second Battle of the Piave River and recognizing the dire internal situation of Austria-Hungary caused by the course of the war and the blockade of the Adriatic at sea, the Royal Italian Army launched a major offensive: the Italian victory marked the end of the war on the Italian Front and the dissolution of the Austro-Hungarian Empire, contributing to the end of the First World War just one week…', 1918, 11, 4, 1918, 11, 3, 'day', '4 November 1918 – 3 November 1918', 65, 'https://en.wikipedia.org/wiki/Battle_of_Vittorio_Veneto'),
  ('Q543255', 'Battle of Taranto', 'The Battle of Taranto, also known as the Raid on Taranto, and Operation Judgement took place on the night of 11/12 November 1940 during the Second World War between British naval forces (Admiral Andrew Cunningham) and Italian naval forces (Admiral Inigo Campioni). The Royal Navy launched the first all-aircraft ship-to-ship naval attack, employing 21 Fairey Swordfish biplane torpedo-bombers from the aircraft carrier HMS Illustrious in the Mediterranean Sea.', 1940, 11, 11, 1940, 11, 12, 'day', '11 November 1940 – 12 November 1940', 68, 'https://en.wikipedia.org/wiki/Battle_of_Taranto'),
  ('Q162333', 'Italian Campaign', 'The Italian campaign of World War II, also called the Liberation of Italy following the German occupation in September 1943, consisted of Allied and Axis operations in and around Italy, from 1943 to 1945. The joint Allied Forces Headquarters (AFHQ) was operationally responsible for all Allied land forces in the Mediterranean theatre and it planned and led the invasion of Sicily in July 1943, followed in September by the invasion of the Italian mainland and the campaign in Italy until the surrender of the Axis forces in Italy in May 1945.', 1943, 7, 10, 1945, 5, 2, 'day', '10 July 1943 – 2 May 1945', 72, 'https://en.wikipedia.org/wiki/Italian_campaign_(World_War_II)'),
  ('Q217981', 'Allied invasion of Sicily', 'The Allied invasion of Sicily, also known as the Battle of Sicily and Operation Husky, was a major campaign of World War II in which Allied forces invaded the Italian island of Sicily in July 1943 and took it from the Axis forces. The island was defended by the Italian 6th Army and the German XIV Panzer Corps.', 1943, 7, 9, 1943, 8, 17, 'day', '9 July 1943 – 17 August 1943', 76, 'https://en.wikipedia.org/wiki/Allied_invasion_of_Sicily'),
  ('Q714777', 'Allied invasion of Italy', 'The Allied invasion of Italy was the Allied amphibious landing on mainland Italy that took place from 3 September 1943, during the Italian campaign of World War II. The operation was undertaken by General Sir Harold Alexander''s 15th Army Group (comprising General Mark W. Clark''s American Fifth Army and General Bernard Montgomery''s British Eighth Army) and followed the successful Allied invasion of Sicily. A preliminary landing in Calabria (Operation Baytown) took place on 3 September, the main invasion force landed on the west coast of Italy at Salerno on 9 September as part of Operation…', 1943, 9, 17, 1943, 9, 16, 'day', '17 September 1943 – 16 September 1943', 67, 'https://en.wikipedia.org/wiki/Allied_invasion_of_Italy'),
  ('Q335288', 'Battle of Monte Cassino', 'The Battle of Monte Cassino, also known as the Battle for Rome, was a series of four military assaults by the Allies against Axis forces in Italy during the Italian Campaign of World War II. The objective was to break through the Winter Line and facilitate an advance towards Rome. In the beginning of 1944, the western half of the Winter Line was anchored by German forces holding the Rapido-Gari, Liri, and Garigliano valleys and several surrounding peaks and ridges.', 1944, 1, 17, 1944, 5, 18, 'day', '17 January 1944 – 18 May 1944', 74, 'https://en.wikipedia.org/wiki/Battle_of_Monte_Cassino'),
  ('Q696844', 'Battle of Anzio', 'The Battle of Anzio was a battle of the Italian Campaign of World War II that commenced 22 January 1944. The battle began with the Allied amphibious landing known as Operation Shingle, and ended on 4 June 1944, with the liberation of Rome.', 1944, 1, 22, 1944, 6, 5, 'day', '22 January 1944 – 5 June 1944', 68, 'https://en.wikipedia.org/wiki/Battle_of_Anzio'),
  ('Q2260521', 'Italian constitutional referendum, 1946', 'An institutional referendum (Italian: referendum istituzionale, or referendum sulla forma istituzionale dello Stato) was held by universal suffrage in the Kingdom of Italy on 2 June 1946, a key event of contemporary Italian history. Until 1946, Italy was a kingdom ruled by the House of Savoy, reigning since the unification of Italy in 1861 and previously rulers of the Kingdom of Sardinia.', 1946, 6, 2, NULL, NULL, NULL, 'day', '2 June 1946', 67, 'https://en.wikipedia.org/wiki/1946_Italian_institutional_referendum'),
  ('Q858734', 'Superga air disaster', 'The Superga air disaster (Italian: Tragedia di Superga, "Tragedy of Superga") occurred on 4 May 1949, when a Fiat G.212 airliner of Avio Linee Italiane, carrying the entire Torino football team (popularly known as the Grande Torino), crashed into the retaining wall at the back of the Basilica of Superga, which stands on a hilltop near Turin, Italy. All thirty-one people on board were killed.', 1949, 5, 4, NULL, NULL, NULL, 'day', '4 May 1949', 67, 'https://en.wikipedia.org/wiki/Superga_air_disaster'),
  ('Q4850939', 'Years of Lead', 'The Years of Lead (Italian: Anni di piombo) were a period of social and political turmoil in Italy that lasted from the late 1960s to the late 1980s, marked by a wave of both far-left and far-right political terrorism. The Years of Lead are sometimes considered to have begun with the 1968 movement in Italy and the Hot Autumn strikes starting in 1969; the death of the policeman Antonio Annarumma in November 1969; the Piazza Fontana bombing in December of that year, which killed 17 and was perpetrated by right-wing terrorists in Milan; and the death shortly after of anarchist worker Giuseppe…', 1970, NULL, NULL, 1982, NULL, NULL, 'decade', '1970s – 1982', 65, 'https://en.wikipedia.org/wiki/Years_of_Lead_(Italy)'),
  ('Q933745', 'Treaty of Osimo', 'The Treaty of Osimo was signed on 10 November 1975 by Italy and Yugoslavia in Osimo, Italy, to definitively divide the Free Territory of Trieste between the two states: the port city of Trieste with a narrow coastal strip to the north-west (Zone A) was given to Italy; a portion of the north-western part of the Istrian peninsula (Zone B) was given to Yugoslavia. The full name of the treaty is Treaty on the delimitation of the frontier for the part not indicated as such in the Peace Treaty of 10 February 1947.', 1975, 11, 10, NULL, NULL, NULL, 'day', '10 November 1975', 66, 'https://en.wikipedia.org/wiki/Treaty_of_Osimo'),
  ('Q838958', 'Rome Statute of the International Criminal Court', 'The Rome Statute of the International Criminal Court is the treaty that established the International Criminal Court (ICC). It was adopted at a diplomatic conference in Rome, Italy on 17 July 1998 and entered into force on 1 July 2002.', 1998, 7, 17, NULL, NULL, NULL, 'day', '17 July 1998', 78, 'https://en.wikipedia.org/wiki/Rome_Statute'),
  ('Q207918', '2009 L''Aquila earthquake', 'An earthquake occurred in the region of Abruzzo, in southern Italy, at 03:32 CEST (01:32 UTC) on 6 April 2009. It measured 6.3 on the moment magnitude scale and 5.8 or 5.9 on the Richter scale; its epicentre was near L''Aquila, the capital of Abruzzo, which together with surrounding villages suffered the most damage.', 2009, 4, 6, NULL, NULL, NULL, 'day', '6 April 2009', 70, 'https://en.wikipedia.org/wiki/2009_L''Aquila_earthquake'),
  ('Q38821', '2012 Northern Italy earthquakes', 'In May 2012, two major earthquakes struck Northern Italy, causing 27 deaths and widespread damage. The events are known in Italy as the 2012 Emilia earthquakes, because they mainly affected the Emilia region.', 2012, 5, 20, 2012, 5, 29, 'day', '20 May 2012 – 29 May 2012', 64, 'https://en.wikipedia.org/wiki/2012_Northern_Italy_earthquakes'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q26689701', 'August 2016 Central Italy earthquake', 'An earthquake, measuring 6.2 ± 0.016 on the moment magnitude scale, hit Central Italy on 24 August 2016 at 03:36:32 CEST (01:36 UTC). Its epicentre was close to Accumoli, with its hypocentre at a depth of 4 ± 1 km, approximately 75 km (47 mi) southeast of Perugia and 45 km (28 mi) north of L''Aquila, in an area near the borders of the Umbria, Lazio, Abruzzo and Marche regions.', 2016, 8, 24, NULL, NULL, NULL, 'day', '24 August 2016', 73, 'https://en.wikipedia.org/wiki/August_2016_Central_Italy_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods');
